package com.gk.jobhelper.dto;
public class RecruitmentPositionExtractionResponse {private Long noticeId;private int attachmentCount,positionCount,failedAttachmentCount;public RecruitmentPositionExtractionResponse(){}public RecruitmentPositionExtractionResponse(Long id,int attachments,int positions,int failed){noticeId=id;attachmentCount=attachments;positionCount=positions;failedAttachmentCount=failed;}public Long getNoticeId(){return noticeId;}public void setNoticeId(Long v){noticeId=v;}public int getAttachmentCount(){return attachmentCount;}public void setAttachmentCount(int v){attachmentCount=v;}public int getPositionCount(){return positionCount;}public void setPositionCount(int v){positionCount=v;}public int getFailedAttachmentCount(){return failedAttachmentCount;}public void setFailedAttachmentCount(int v){failedAttachmentCount=v;}}
